/**
 * Oridecon Admin — synchronous head bootstrap.
 *
 * Generated by dev/generators/admin_shell_assets.py — do not edit by hand.
 * Loaded without defer so the dark-mode class and theme overrides apply
 * before first paint; no DOM body access is allowed here.
 */
(function () {
  var root = document.documentElement;
  var stored = localStorage.getItem('darkMode');
  var serverDefault = root.getAttribute('data-admin-dark-mode') || '';
  var dark = stored !== null ? stored === 'true'
    : serverDefault ? serverDefault === 'dark'
    : window.matchMedia('(prefers-color-scheme: dark)').matches;
  if (dark) root.classList.add('dark');
})();

window.toggleTheme = function () {
  var dark = !document.documentElement.classList.contains('dark');
  document.documentElement.classList.toggle('dark', dark);
  localStorage.setItem('darkMode', String(dark));
  window.dispatchEvent(new CustomEvent('darkmode-change', { detail: { dark: dark } }));
};

/* Runtime theme override (was AdminShell <style id="admin-theme-css">).
   The default palette lives in admin.css; only a configured primary color
   needs to be re-applied as CSS custom properties. */
(function () {
  var primary = document.documentElement.getAttribute('data-admin-primary-color');
  if (!primary) return;
  var style = document.documentElement.style;
  style.setProperty('--primary', primary);
  style.setProperty('--ring', primary);
  style.setProperty('--primary-foreground', 'oklch(1 0 0)');
})();
